    この日は安定板を使っている（投票画面に「安定板」の表示）。荒天用の装備で、
    付けると全体に遅くなり差が付きにくいと言われる。モデルに項目は無い。
    直前情報「2R時点」は風速7m・波高7cmだったが、結果ページは5m・5cm。
